        "description":  "El ROTOTRON RTS de IKA es un agitador de flujo a chorro para diversos usos, el cual combina la funcionalidad de un equipo de agitación convencional con las propiedades de un dispersor equipado con rotor/estator. Las máquinas de tipo RTS se emplean en tareas tales como homogeneizar, dispersar, suspender, emulsionar, airear y disolver, así como facilitar el intercambio de calor. La alta velocidad de operación del rotor en conjunto con la distancia reducida entre las aspas de mezclado y el tubo inyector evitan pérdidas por contracorriente. Como tal, el agitador de flujo a chorro se distingue por su alta eficiencia de energía, al circular y mezclar los productos intensivamente mientras consume poca energía. Los agitadores ROTOTRON RTS de IKA pueden mezclar fluidos con una viscosidad de hasta 15,000 cP. El agitador ROTOTRON RTS se suministra en 4 tamaños estándar y se cuenta con opciones para la instalación en tanques abiertos o cerrados. Opcionalmente, el ROTOTRON RTS es disponible con diferentes opciones: desde el control de velocidad variable del motor, una versión a prueba de explosión, hasta un diseño caracterizado para uso farmacéutico. Esto hace que el ROTOTRON RTS sea ideal para aplicaciones en las industrias química, de papel, pintura y barnices, así como en las industrias alimenticia y farmacéutica Rototron RTS \u003e Industria alimentaria: helados, chocolate, aromas y bebidas. \u003e Pinturas y tintes: tintas y acuarelas. \u003e Industria papelera: adhesivos y pasta de papel. \u003e Industria química: tintes, fertilizantes y pesticidas.",
