        "line":  "IKA Laboratorio",
        "category":  "Termostatos",
        "description":  "Refrigerador de circulación de alta eficiencia energética y temperatura estable, con exclusivo controlador inalámbrico. Con una gran potencia frigorífica de 400 W, está concebido para tareas de refrigeración hasta -30 °C. La bomba PEEK controlada por velocidad permite un ajuste continuo e indirecto de la presión máxima y del caudal. Su excelente estabilidad de temperatura de ± 0,05 K (a -10 °C) puede manejar incluso las aplicaciones más exigentes. El embudo de llenado integrado y la válvula de descarga posibilitan la manipulación segura y limpia del termofluido. La tapa frontal de fácil apertura permite limpiar cómodamente el filtro de aire. Gracias al reservorio del baño de 4 litros perfectamente aislado, se dispone de hasta 2,5 litros de termofluido para el circuito de refrigeración externo sin necesidad de rellenar. El volumen de suministro incluye un sensor de temperatura PT 100 externo.",
