        "slug":  "unistat-520w",
        "name":  "Unistat 520w",
        "line":  "Huber",
        "category":  "Unistats Huber",
        "description":  "Los Unistats de la serie 500 con capacidad de refrigeración de hasta 35 kW son excepcionalmente adecuados para aplicaciones de control de temperatura en la técnica de procesos y procedimientos químicos en diferentes ramas de la industria. Han sido diseñados para tareas en ingeniería química y procesos, tales como control de temperatura de reactores, autoclaves, miniplantas, plantas piloto, bloques de reacción y calorímetros. Estos sistemas de control de temperatura ofrecen una termodinámica única para resultados reproducibles y de alta precisión. En ello, la tecnología Unistat garantiza velocidades de enfriamiento y calentamiento rápidas, así como rangos de temperatura muy amplios sin tener que cambiar el fluido térmico. El manejo se lleva a cabo en todos los Unistats a través de una pantalla táctil a color de 5.7“con una cómoda guía de menú. • Hasta -55°C de temperatura de trabajo • Hasta 35 kW de potencia frigorífica • Hasta 200 I/min de capacidad de Bombeo • Regulador de pantalla táctil",
