        "description":  "VARIOSTAT termostato de recirculación de frío para recipientes de baño variables. El Variostat puede atemperar cualquier recipiente de baño de dimensiones arbitrarias. El diseño especial permite una gran flexibilidad para el usuario. Con la bomba de succión/presión de regulación sin fases se puede adaptar de manera óptima la recirculación al tamaño de baño correspondiente. Además, la presión de la bomba puede ser ajustada y regulada de forma controlada por un menú para aplicaciones externas con un sensor de presión opcional. Las cubetas aisladas de acero inoxidable están disponibles en tres tamaños estándar o en las dimensiones deseadas como accesorios. • Hasta -30 °C Rango de temperatura de trabajo • Hasta 0,3 kW Potencia calorífica • Hasta 25 I/ min Capacidad de bombeo",
