        "category":  "Agitadores De Mecanicos",
        "description":  "Extremadamente potente agitador de laboratorio para aplicaciones de alta viscosidad y mezclado intensivo para cantidades máximas de 100 l (H2O). Diseñado con un controlador inalámbrico extraíble y una pantalla TFT digital. Ajusta automáticamente la velocidad mediante tecnología de control por microprocesador dentro del rango de velocidades de 0/6 a 2000 rpm (dos rangos de viscosidades). El agitador está equipado con puertos RS 232 y USB para controlar y documentar todos los parámetros. Tendencia del torque integrado en la pantalla para la medición de los cambios de viscosidad. Los circuitos de seguridad instalados garantizan la desconexión automática en condiciones de atascamiento o sobrecarga. Se mantiene una comparación continua de la velocidad del eje con la velocidad deseada y las variaciones se ajustan automáticamente. De este modo se garantiza una velocidad constante incluso con cambios en las viscosidades de la muestra.",
