        "line":  "IKA Laboratorio",
        "category":  "IKA Laboratorio",
        "description":  "MINISTATS termostatos para recirculación y baño de enfriamiento más pequeños Ministats son los termostatos de refrigeración más pequeños del mundo y posibilitan un servicio en el espacio más estrecho, por ejemplo, en una campana extractora de laboratorio o dentro de instalaciones técnicas. Los dispositivos están ampliamente equipados y se adaptan perfectamente al control de temperatura de fotómetros, refractómetros, viscosímetros, aparatos de destilación, recipientes de reacción e instalaciones de miniplantas. El objetivo esencial de aplicación se encuentra en aplicaciones externas; no obstante, la abertura del baño también permite el control de temperatura de pequeños objetos directamente en el baño del termostato. • Hasta -45 °C Rango de temperatura de trabajo • Hasta 0,6 kW Potencia calorífica • Hasta 22 I/ min Capacidad de bombeo",
