        "name":  "Planta Compacta de Mezcla y Dispersión (XPP).",
        "line":  "IKA Laboratorio",
        "category":  "Agitadores Verticales",
        "description":  "La planta compacta de mezcla y dispersión (XPP) de IKA, se ha diseñado para fabricar productos especiales con un contenido de sólidos especialmente alto, también con tiempos de lote cortos. Grandes cantidades de sólidos en polvo y aditivos líquidos se incorporan de forma eficaz y homogénea a un líquido. Este rendimiento extremo de mezcla y dispersión se consigue gracias a la mezcladora en línea CMX integrada en el suelo de la planta. De diseño compacto, la XPP de fácil manejo es su planta de proceso ideal. Aplicaciones: \u003e Desinfectantes \u003e Dispersión de pigmentos \u003e Rellenos de fruta \u003e Selladores \u003e Lacas \u003e Pintura interior \u003e Hidrocoloides/espesantes \u003e Recubrimientos de electrodos \u003e Protectores solares \u003e Adhesivos",
