        "line":  "IKA Laboratorio",
        "category":  "Agitadores Verticales",
        "description":  "Baños termostáticos y de circulación con baño abierto, para control de temperatura interna y externa Baños termostáticos de calefacción para el control de temperatura de aplicaciones externas conectadas. Además, existe la posibilidad de regular la temperatura de cualquier objeto directamente en el baño del termostato abierto. Los dispositivos están equipados con recipientes de baño de larga duración y acero inoxidable de alta calidad y poseen de serie conexiones de bombas en la parte posterior. Todos los modelos están equipados con protección contra sobre temperatura y bajo nivel de acuerdo con la clase de protección III (FL), según la DIN 12876 para el empleo con líquidos in amables. • Hasta +300 °C Rango de temperatura • Hasta 3,5 kW Potencia calorífica • Hasta 27 I/ min Capacidad de bombeo",
